NODE_PATH=/tmp/node_modules node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search hotel_reservations
let r = db.prepare(\"SELECT * FROM hotel_reservations WHERE reservation_id = 'C4C633'\").get();
if (r) { console.log('HOTEL RESERVATION:'); console.log(JSON.stringify(r, null, 2)); }

// Search flight_bookings
r = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C4C633'\").get();
if (r) { console.log('FLIGHT BOOKING:'); console.log(JSON.stringify(r, null, 2)); }

// Search car_rentals
r = db.prepare(\"SELECT * FROM car_rentals WHERE rental_id = 'C4C633'\").get();
if (r) { console.log('CAR RENTAL:'); console.log(JSON.stringify(r, null, 2)); }

// Search orders
r = db.prepare(\"SELECT * FROM orders WHERE order_id = 'C4C633'\").get();
if (r) { console.log('ORDER:'); console.log(JSON.stringify(r, null, 2)); }

// Brute force search
for (const t of ['hotel_reservations','flight_bookings','car_rentals','orders','users','carts']) {
  const rows = db.prepare('SELECT * FROM ' + t + ' WHERE 1=1').all();
  for (const row of rows) {
    for (const [k,v] of Object.entries(row)) {
      if (String(v).includes('C4C633')) {
        console.log('Found in table:', t, ', column:', k, ', value:', v);
        console.log(JSON.stringify(row, null, 2));
      }
    }
  }
}
"

